#!/bin/bash
# Generated by reef-eval's EdgeBench converter. Runs in the SEPARATE verifier
# container (built from the judge image). Harbor re-materializes the declared
# submission artifacts at their original paths before this script runs; the
# checks below just make a missing submission loud.
set -uo pipefail
mkdir -p /logs/verifier

[ -e "/home/workspace/smt_solver/build.sh" ] || echo "WARNING: submission missing: /home/workspace/smt_solver/build.sh"
[ -e "/home/workspace/smt_solver/solve" ] || echo "WARNING: submission missing: /home/workspace/smt_solver/solve"
[ -e "/home/workspace/smt_solver/src" ] || echo "WARNING: submission missing: /home/workspace/smt_solver/src"

cd /home/workspace/smt_solver
OUT=$(python3 - <<'PY'
import pathlib, shutil, zipfile
zip_path = pathlib.Path('/home/workspace/smt_judge/SMT-hidden_benchmarks.zip')
dest = pathlib.Path('/home/workspace/smt_judge/hidden_benchmarks')
if dest.exists():
    shutil.rmtree(dest)
dest.mkdir(parents=True, exist_ok=True)
with zipfile.ZipFile(zip_path) as z:
    z.extractall(dest)
PY
cd /home/workspace/smt_solver && rm -rf benchmarks hidden_benchmarks scripts expected_answers.json selection_manifest.json hidden_score.json public_score.json; chmod +x build.sh solve; build_status=0; ./build.sh >/tmp/smt_build.out 2>/tmp/smt_build.err || build_status=$?; if [ "$build_status" -eq 0 ]; then python3 /home/workspace/smt_judge/scripts/evaluate.py --solver ./solve --benchmarks /home/workspace/smt_judge/hidden_benchmarks --expected /home/workspace/smt_judge/hidden_benchmarks/expected_answers.json --manifest /home/workspace/smt_judge/hidden_benchmarks/selection_manifest.json --timeout 60 --parallel 16 --perturb --perturb-salt hidden-sebench --submission-root /home/workspace/smt_solver --output /tmp/smt_hidden_score.json >/tmp/smt_eval.out 2>/tmp/smt_eval.err; eval_status=$?; else eval_status=$build_status; fi; if [ -f /tmp/smt_build.out ]; then cat /tmp/smt_build.out; fi; if [ -f /tmp/smt_build.err ]; then cat /tmp/smt_build.err; fi; if [ -f /tmp/smt_eval.out ]; then cat /tmp/smt_eval.out; fi; if [ -f /tmp/smt_eval.err ]; then cat /tmp/smt_eval.err; fi; cat > /tmp/sebench_parse_result.py <<'PY'
import json, pathlib
p = pathlib.Path('/tmp/smt_hidden_score.json')
raw = json.loads(p.read_text()) if p.exists() else {'final_score': 0.0, 'logic_summary': {}}
raw_score = float(raw.get('final_score', 0.0) or 0.0)
score = raw_score / 100.0 if raw_score > 1.0 else raw_score
by = raw.get('logic_summary', {}) or {}
def clean(g):
    out = {}
    for k, item in sorted(g.items()):
        t = int(item.get('total', 0) or 0); c = int(item.get('correct', 0) or 0)
        out[k] = {'total': t, 'correct': c, 'wrong': int(item.get('wrong', max(0, t-c)) or 0), 'timeout': int(item.get('timeout', 0) or 0), 'unknown': int(item.get('unknown', 0) or 0), 'error': int(item.get('error', 0) or 0), 'no_reference': int(item.get('no_reference', 0) or 0), 'invalid_model': int(item.get('invalid_model', 0) or 0), 'score': float(item.get('score', 0.0) or 0.0)}
    return out
by = clean(by)
total = sum(v['total'] for v in by.values()); correct = sum(v['correct'] for v in by.values())
wrong = max(0, total - correct)
result = {'valid': True, 'score': score, 'pass_rate': correct/total if total else 0.0, 'total_tests': total, 'passed': correct, 'failed': wrong, 'errors': 0, 'summary': 'score={:.6f} ({:.2f}/100), correct={}/{}'.format(score, 100*score, correct, total), 'details': [], 'metrics': {'score': score, 'score_percent': 100*score, 'total': total, 'correct': correct, 'wrong_or_failed': wrong, 'by_logic': by}}
print('>>>>> Start Structured Result')
print(json.dumps(result, ensure_ascii=False))
print('>>>>> End Structured Result')
PY
python3 /tmp/sebench_parse_result.py 2>&1)
EC=$?
echo "$OUT" | tail -40
printf '%s' "$OUT" | python3 /tests/parse_score.py
echo "eval exit code: $EC" > /logs/verifier/eval_exit_code.txt
